        self,
        *,
        stable_device_key: str,
        plugin_id: str,
        vendor: str | None = None,
        model: str | None = None,
        serial: str | None = None,
        friendly_name: str | None = None,
        alias: str | None = None,
        role: str | None = None,
        last_source_id: str | None = None,
    ) -> None:
        if self.read_only:
            return
        con = self._require()
        now = _utc_now()
        with con:
            existing = con.execute(
                "SELECT first_seen_utc FROM devices WHERE stable_device_key=?",
                (stable_device_key,),
            ).fetchone()
            if existing is None:
                con.execute(
                    """
