                      stable_device_key, plugin_id, vendor, model, serial,
                      friendly_name, alias, role, first_seen_utc, last_seen_utc,
                      last_source_id
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        stable_device_key,
                        plugin_id,
                        vendor,
                        model,
                        serial,
                        friendly_name,
                        alias,
                        role,
                        now,
                        now,
                        last_source_id,
                    ),
                )
            else:
                con.execute(
                    """
                    UPDATE devices SET
                      plugin_id=?, vendor=?, model=?, serial=?,
